const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const {chromium} = require('playwright');
const version = require('playwright/package.json').version;
const corePackage = require.resolve('playwright-core/package.json');
const coreVersion = require(corePackage).version;
const browsers = JSON.parse(fs.readFileSync(path.join(path.dirname(corePackage), 'browsers.json'), 'utf8'));
const shell = browsers.browsers.find(item => item.name === 'chromium-headless-shell');
if (version !== '1.60.0' || coreVersion !== version || !shell || shell.revision !== '1223' || shell.browserVersion !== '148.0.7778.96') throw new Error('unexpected App Playwright/browser identity');
const executable = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE;
if (!path.isAbsolute(executable) || !fs.statSync(executable).isFile()) throw new Error('browser executable missing or not absolute');
fs.accessSync(executable, fs.constants.X_OK);
(async () => {
  const browser = await chromium.launch({headless: true, executablePath: executable});
  const browserVersion = browser.version();
  await browser.close();
  if (browserVersion !== shell.browserVersion) throw new Error(`unexpected launched browser version: ${browserVersion}`);
  const result = {playwright_version: version, playwright_core_version: coreVersion, browser_revision: shell.revision, expected_browser_version: shell.browserVersion, launched_browser_version: browserVersion, browsers_path: process.env.PLAYWRIGHT_BROWSERS_PATH, executable: fs.realpathSync(executable), executable_sha256: crypto.createHash('sha256').update(fs.readFileSync(executable)).digest('hex'), isolated_home: process.env.HOME, launch: 'success'};
  fs.writeFileSync(path.join(process.env.GITHUB_WORKSPACE, 'out/t3/browser-identity.json'), JSON.stringify(result, null, 2) + '\n');
  console.log(JSON.stringify(result));
})().catch(error => { console.error(error); process.exitCode = 1; });
BROWSER_PREFLIGHT
)
